        "code": "import crypto from 'node:crypto';\n\nexport interface NormalizedLeadIdentity {\n  phoneE164: string;\n  phoneSha256: string;\n  idempotencyKey: string;\n}\n\nexport function normalizeVietnamPhoneE164(rawInput: string): string {\n  let digits = rawInput.replace(/\\D+/g, '');\n  if (!digits) throw new Error('EMPTY_PHONE');\n\n  if (digits.startsWith('840') && digits.length >= 11) {\n    digits = '84' + digits.slice(3);\n  } else if (digits.startsWith('0')) {\n    digits = '84' + digits.slice(1);\n  } else if (!digits.startsWith('84') && digits.length === 9) {\n    digits = '84' + digits;\n  }\n\n  if (!/^84[35789]\\d{8}$/.test(digits)) {\n    throw new Error(`INVALID_VN_MOBILE: ${digits}`);\n  }\n  return `+${digits}`;\n}\n\nexport function buildLeadIdentity(rawPhone: string, sourceEventId: string): NormalizedLeadIdentity {\n  const phoneE164 = normalizeVietnamPhoneE164(rawPhone);\n  const phoneSha256 = crypto.createHash('sha256').update(phoneE164.slice(1)).digest('hex');\n  return { phoneE164, phoneSha256, idempotencyKey: `evt_${sourceEventId}` };\n}\n\n// PostgreSQL 180-day Golden Record lookup:\n// SELECT id, assigned_owner_id FROM crm_golden_leads\n// WHERE phone_sha256 = $1 AND created_at >= NOW() - INTERVAL '180 days'\n// FOR UPDATE SKIP LOCKED;"
